mapper.select:
SELECT /* LGVPAYCOMM.retrieveEmployee */ em.employee_number AS employee_no , em.full_name_local AS employee_name , em.grade AS grade_code , em.grade_title ,(SELECT lgvhr_common_pkg.decode_lookup('IF_VIETNAM_GRADE_TITLE', em.grade_title, NULL, #{USER_SESSION.languageCode}) FROM DUAL) as grade_title_name , em.grade_type AS emp_category_name , em.organization_id , um.default_org_id , em.org_name_local AS organization_name , em.attribute10 AS shift_type_code , em.job_family||'.'||em.job_group||'.'||em.job_detail AS work_type_name , em.assignment_category AS employment_category_code /* 재량권 조회시 사용 */ ,(SELECT lgvhr_common_pkg.decode_lookup('LGVHR_SHIFT_TYPE_CODE', em.attribute10, NULL, #{USER_SESSION.languageCode}) FROM DUAL) AS shift_type_name , um.application_user_id , um.mail_addr , cv.organization_id AS operating_unit_id , lgvhr_common_pkg.get_org_resp_flag_func(em.subsidiary_code, em.employee_number, TRUNC(SYSDATE)) AS org_resp_flag /* 조직책임자 여부 */ , em.subsidiary_code , um.language_code , em.fse_yn /* FSE 여부 */ , em.flsa_yn /* 단기파견자 여부 */ FROM emp_master em , lgcom_user_m um , lgcom_company_v cv
WHERE em.employee_number = #{USER_SESSION.userName}
WHERE em.employee_number = #{employeeNo}
AND um.user_name = em.employee_number AND cv.short_code = em.subsidiary_code
UNION ALL SELECT um.user_name AS employee_no , um.local_language_full_name AS employee_name , NULL AS grade_code , NULL AS grade_title , um.grade_title_name as grade_title_name , NULL AS emp_category_name , NULL , um.default_org_id , NULL AS organization_name , NULL AS shift_type_code , NULL AS work_type_name , NULL AS employment_category_code /* 재량권 조회시 사용 */ , NULL AS shift_type_name , um.application_user_id , um.mail_addr , cv.organization_id AS operating_unit_id , NULL AS org_resp_flag /* 조직책임자 여부 */ , cv.short_code AS subsidiary_code , um.language_code , NULL AS fse_yn /* FSE 여부 */ , NULL AS flsa_yn /* 단기파견자 여부 */ FROM lgcom_user_m um , lgcom_company_v CV , lgcom_common_code_c cc
WHERE um.user_name = #{USER_SESSION.userName}
WHERE um.user_name = #{employeeNo}
AND cv.organization_id = um.default_org_id AND cc.code_type_code = 'LGVCOM_SYSTEM_ADMIN_ID' /* system admin */ AND cc.common_code = um.user_name AND cc.use_flag = 'Y' AND trunc(SYSDATE) BETWEEN cc.apply_start_date AND NVL(cc.apply_end_date, trunc(SYSDATE))
